"use client";

import { cn } from "@/lib/utils";
import { ProblemHeader } from "./problem-header";
import { ProblemDescription } from "./problem-description";
import { ProblemTestCases } from "./problem-test-cases";
import { ProblemResult } from "./problem-result";
import type {
  ProblemDetailCaseResult,
  ProblemDetailProblem,
  ProblemDetailSubmission,
  ProblemDetailTestCase,
} from "./problem-types";

export interface ProblemDetailEditor {
  title: string;
  onTitleChange: (value: string) => void;
  description: string;
  onDescriptionChange: (value: string) => void;
  /** Whether the description is currently shown as an editable field. */
  editing: boolean;
  onStartEdit: () => void;
  onSave: () => void;
  onCancel: () => void;
  busy?: boolean;
  error?: string | null;
}

export interface ProblemDetailProps {
  problem: ProblemDetailProblem;
  cases: ProblemDetailTestCase[];
  /** Latest judge result for the verdict panel; pass null to show the empty state. */
  result?: ProblemDetailSubmission | null;
  /** Per-case judge breakdown, if available. */
  caseResults?: ProblemDetailCaseResult[] | null;
  judging?: boolean;
  timedOut?: boolean;
  error?: { message: string } | null;
  runMode?: boolean;
  /** Hide hidden testcases from the examples list. */
  showHiddenCases?: boolean;
  /** Render the public testcases section. */
  showTestCases?: boolean;
  /** Render the judge verdict panel. */
  showResult?: boolean;
  /** When provided, the title and description become editable. */
  editor?: ProblemDetailEditor;
  /** Extra controls rendered in the header, e.g. a watchlist toggle. */
  actions?: React.ReactNode;
  className?: string;
}

/**
 * Problem Detail block.
 *
 * Data-driven composition of the judge problem view: header (id, title,
 * difficulty, lifecycle), markdown description with time/memory limits, public
 * test cases, and a verdict result panel with per-case diffs.
 *
 * Drop-in replacement for the description column of the practice workspace:
 *
 * ```tsx
 * <ProblemDetail
 *   problem={problem}
 *   cases={cases}
 *   result={judge.result}
 *   caseResults={judge.cases}
 *   judging={judge.judging}
 *   timedOut={judge.timedOut}
 *   error={judge.error}
 * />
 * ```
 */
export function ProblemDetail({
  problem,
  cases,
  result = null,
  caseResults = null,
  judging = false,
  timedOut = false,
  error = null,
  runMode = false,
  showHiddenCases = true,
  showTestCases = true,
  showResult = true,
  editor,
  actions,
  className,
}: ProblemDetailProps) {
  return (
    <div className={cn("h-full overflow-auto", className)}>
      <div className="sticky top-0 z-10 border-b bg-card px-3 pt-2">
        <span className="inline-flex items-center gap-1.5 rounded-t-md bg-secondary px-3 py-1.5 text-sm">
          Description
        </span>
      </div>

      <div className="space-y-5 p-6">
        <ProblemHeader
          id={problem.id}
          title={problem.title}
          difficulty={problem.difficulty}
          status={problem.status}
          likes={problem.likes}
          dislikes={problem.dislikes}
          actions={actions}
          editor={
            editor
              ? {
                  title: editor.title,
                  onTitleChange: editor.onTitleChange,
                  editing: editor.editing,
                  onStartEdit: editor.onStartEdit,
                }
              : undefined
          }
        />

        <ProblemDescription
          markdown={problem.description}
          timeLimitMs={problem.timeLimitMs}
          memoryLimitMb={problem.memoryLimitMb}
          editor={
            editor
              ? {
                  value: editor.description,
                  onChange: editor.onDescriptionChange,
                  editing: editor.editing,
                  onSave: editor.onSave,
                  onCancel: editor.onCancel,
                  busy: editor.busy,
                  error: editor.error,
                }
              : undefined
          }
        />

        {showTestCases ? (
          <ProblemTestCases cases={cases} showHidden={showHiddenCases} />
        ) : null}

        {showResult ? (
          <section aria-label="Judge result" className="rounded-lg border">
            <ProblemResult
              result={result}
              cases={caseResults}
              judging={judging}
              timedOut={timedOut}
              error={error}
              runMode={runMode}
            />
          </section>
        ) : null}
      </div>
    </div>
  );
}

export { ProblemHeader } from "./problem-header";
export { ProblemDescription } from "./problem-description";
export { ProblemTestCases } from "./problem-test-cases";
export { ProblemResult } from "./problem-result";
export { ProblemDiffView } from "./problem-diff-view";
export * from "./problem-types";

"use client";

import { Pencil, ThumbsDown, ThumbsUp } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import {
  PROBLEM_DIFFICULTY_META,
  type ProblemDifficulty,
} from "./problem-types";

export interface ProblemHeaderEditor {
  /** Current draft title. */
  title: string;
  onTitleChange: (value: string) => void;
  /** Whether the title is currently shown as an editable field. */
  editing: boolean;
  /** Enter edit mode. */
  onStartEdit: () => void;
}

export interface ProblemHeaderProps {
  id: number;
  title: string;
  difficulty: ProblemDifficulty;
  status?: string;
  likes?: number | null;
  dislikes?: number | null;
  /** When provided, the title becomes editable. */
  editor?: ProblemHeaderEditor;
  /** Extra controls rendered alongside the votes, e.g. a watchlist toggle. */
  actions?: React.ReactNode;
  className?: string;
}

/**
 * Title, difficulty, lifecycle status and vote counts for a problem.
 *
 * Composed from shadcn `Badge` and `Input` so it inherits the host's theme
 * tokens.
 */
export function ProblemHeader({
  id,
  title,
  difficulty,
  status,
  likes,
  dislikes,
  editor,
  actions,
  className,
}: ProblemHeaderProps) {
  const diff = PROBLEM_DIFFICULTY_META[difficulty];

  return (
    <div className={cn("space-y-3", className)}>
      <div className="flex flex-wrap items-start justify-between gap-3">
        {editor?.editing ? (
          <Input
            value={editor.title}
            onChange={(e) => editor.onTitleChange(e.target.value)}
            aria-label="Problem title"
            className="h-auto max-w-md text-lg font-semibold"
          />
        ) : (
          <h1 className="text-2xl font-semibold leading-tight">{title}</h1>
        )}

        <div className="flex shrink-0 items-center gap-2">
          {editor && !editor.editing ? (
            <Button
              variant="ghost"
              size="icon"
              aria-label="Edit problem"
              onClick={editor.onStartEdit}
            >
              <Pencil className="h-4 w-4" aria-hidden="true" />
            </Button>
          ) : null}
          {status ? (
            <Badge variant="secondary" className="font-mono font-normal">
              {status}
            </Badge>
          ) : null}
          <Badge variant="outline" className={cn("font-normal", diff.className)}>
            {diff.label}
          </Badge>
        </div>
      </div>

      <div className="flex items-center gap-4 text-xs text-muted-foreground">
        <span className="font-mono">#{id}</span>
        {likes != null ? (
          <span className="flex items-center gap-1">
            <ThumbsUp className="h-3.5 w-3.5" aria-hidden="true" />
            {likes}
          </span>
        ) : null}
        {dislikes != null ? (
          <span className="flex items-center gap-1">
            <ThumbsDown className="h-3.5 w-3.5" aria-hidden="true" />
            {dislikes}
          </span>
        ) : null}
        {actions}
      </div>
    </div>
  );
}

"use client";

import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

export interface ProblemDescriptionProps {
  /** Markdown source. */
  markdown: string;
  timeLimitMs?: number;
  memoryLimitMb?: number;
  /** When provided, renders an editable markdown editor instead of the rendered statement. */
  editor?: {
    value: string;
    onChange: (value: string) => void;
    /** Whether the editor is currently open. */
    editing: boolean;
    onSave: () => void;
    onCancel: () => void;
    busy?: boolean;
    error?: string | null;
  };
  className?: string;
}

/**
 * Markdown problem statement with the judge's resource limits.
 *
 * Uses `prose` from `@tailwindcss/typography` for the body and shadcn
 * `Badge` for the limit chips. When an `editor` is supplied the statement is
 * replaced by an editable markdown textarea, which is how instructors revise
 * a problem from the same surface.
 */
export function ProblemDescription({
  markdown,
  timeLimitMs,
  memoryLimitMb,
  editor,
  className,
}: ProblemDescriptionProps) {
  return (
    <div className={cn("space-y-4", className)}>
      {timeLimitMs != null || memoryLimitMb != null ? (
        <div className="flex flex-wrap gap-2">
          {timeLimitMs != null ? (
            <Badge variant="outline" className="font-mono font-normal">
              Time: {timeLimitMs} ms
            </Badge>
          ) : null}
          {memoryLimitMb != null ? (
            <Badge variant="outline" className="font-mono font-normal">
              Memory: {memoryLimitMb} MB
            </Badge>
          ) : null}
        </div>
      ) : null}

      {editor?.editing ? (
        <div className="space-y-2">
          <Textarea
            value={editor.value}
            onChange={(e) => editor.onChange(e.target.value)}
            aria-label="Markdown content"
            className="min-h-56 font-mono text-xs"
          />
          {editor.error ? (
            <p role="alert" className="text-xs text-destructive">
              {editor.error}
            </p>
          ) : null}
          <div className="flex gap-2">
            <Button size="sm" onClick={editor.onSave} disabled={editor.busy}>
              Save changes
            </Button>
            <Button size="sm" variant="ghost" onClick={editor.onCancel}>
              Cancel
            </Button>
          </div>
        </div>
      ) : (
        <article
          className={cn(
            "prose prose-sm max-w-none dark:prose-invert",
            "prose-code:rounded prose-code:bg-secondary prose-code:px-1 prose-code:py-0.5 prose-code:font-mono",
            "prose-code:text-emerald-600 prose-code:before:content-none prose-code:after:content-none",
            "dark:prose-code:text-emerald-400",
            "prose-pre:bg-secondary"
          )}
        >
          <ReactMarkdown remarkPlugins={[remarkGfm]}>{markdown}</ReactMarkdown>
        </article>
      )}
    </div>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import type { ProblemDetailTestCase } from "./problem-types";

export interface ProblemTestCasesProps {
  cases: ProblemDetailTestCase[];
  /** When false, hidden testcases are omitted from the list. */
  showHidden?: boolean;
  className?: string;
}

/**
 * Public sample testcases rendered as shadcn `Card`-style panels.
 *
 * Hidden cases are flagged rather than hidden outright when `showHidden` is
 * on, so the sample list still communicates how many cases the judge runs.
 */
export function ProblemTestCases({
  cases,
  showHidden = true,
  className,
}: ProblemTestCasesProps) {
  const visible = showHidden ? cases : cases.filter((c) => !c.isHidden);

  return (
    <section className={cn("space-y-3", className)} aria-label="Test cases and examples">
      <h2 className="text-sm font-semibold">Test Cases &amp; Examples</h2>

      {visible.length === 0 ? (
        <p className="text-sm text-muted-foreground">
          No public testcases available yet for this problem.
        </p>
      ) : null}

      {visible.map((c, i) => (
        <div key={c.id} className="space-y-2 rounded-lg border bg-card p-3 text-xs">
          <div className="flex items-center gap-2">
            <p className="font-mono font-medium text-primary">Test Case {i + 1}</p>
            {c.isHidden ? (
              <Badge variant="secondary" className="font-normal">
                hidden
              </Badge>
            ) : null}
          </div>

          {c.input === "" && c.expectedOutput === "" ? (
            <p className="text-muted-foreground">
              Test case content is not available yet.
            </p>
          ) : (
            <>
              <p>
                <span className="text-muted-foreground">Input: </span>
                <span className="whitespace-pre-wrap font-mono text-cyan-600 dark:text-cyan-300">
                  {c.input}
                </span>
              </p>
              <p>
                <span className="text-muted-foreground">Output: </span>
                <span className="whitespace-pre-wrap font-mono">{c.expectedOutput}</span>
              </p>
            </>
          )}

          <p className="text-muted-foreground">
            Explanation: {c.explanation ?? "N/A"}
          </p>
        </div>
      ))}
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Check, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";
import { ProblemDiffView } from "./problem-diff-view";
import {
  PROBLEM_VERDICT_META,
  formatProblemMemory,
  type ProblemCaseVerdict,
  type ProblemDetailCaseResult,
  type ProblemDetailSubmission,
} from "./problem-types";

export interface ProblemResultProps {
  result: ProblemDetailSubmission | null;
  cases?: ProblemDetailCaseResult[] | null;
  judging?: boolean;
  timedOut?: boolean;
  error?: { message: string } | null;
  runMode?: boolean;
  emptyHint?: React.ReactNode;
  /** Message shown when judging exceeded the polling window. */
  timedOutHint?: React.ReactNode;
  /** Label for the memory figure in the verdict banner. */
  memoryLabel?: string;
}

function Spinner() {
  return (
    <span
      className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent"
      aria-hidden="true"
    />
  );
}

function CodeBox({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <p className="mb-1 font-mono text-[11px] uppercase text-muted-foreground">
        {label}
      </p>
      <pre className="overflow-auto whitespace-pre-wrap rounded-md border bg-black/90 px-3 py-2 font-mono text-xs text-white">
        {children}
      </pre>
    </div>
  );
}

const CASE_VERDICT_CLASS: Record<ProblemCaseVerdict, string> = {
  AC: "bg-primary",
  SKIPPED: "bg-muted-foreground",
  WA: "bg-destructive",
  TLE: "bg-destructive",
  MLE: "bg-destructive",
  RE: "bg-destructive",
};

/**
 * Judge verdict summary with a per-testcase breakdown.
 *
 * The verdict banner, status tiles and testcase selector are built from
 * shadcn `Badge` and `Tabs` primitives so the block matches the host theme.
 */
export function ProblemResult({
  result,
  cases,
  judging,
  timedOut,
  error,
  runMode,
  emptyHint = "Run code or submit solution to see results.",
  timedOutHint = "Judging took longer than expected. Your submission has been saved; check the Submissions tab.",
  memoryLabel = "Memory",
}: ProblemResultProps) {
  const [selected, setSelected] = useState(0);

  // Jump to the first failing case whenever a new breakdown arrives.
  useEffect(() => {
    if (!cases) return;
    const firstFailing = cases.findIndex(
      (c) => c.verdict !== "AC" && c.verdict !== "SKIPPED"
    );
    setSelected(Math.max(0, firstFailing));
  }, [cases]);

  if (error) {
    return (
      <div
        role="alert"
        className="m-4 rounded-md border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive"
      >
        {error.message}
      </div>
    );
  }

  if (judging) {
    return (
      <div
        className="flex items-center gap-2 p-4 text-sm text-muted-foreground"
        aria-live="polite"
      >
        <Spinner />
        {result?.status === "JUDGING"
          ? "Evaluating solution…"
          : "Submission received, waiting in judge queue…"}
      </div>
    );
  }

  if (timedOut) {
    return (
      <p className="p-4 text-sm text-amber-600 dark:text-amber-400" role="status">
        {timedOutHint}
      </p>
    );
  }

  if (!result?.verdict) {
    return <p className="p-4 text-sm text-muted-foreground">{emptyHint}</p>;
  }

  const verdict = PROBLEM_VERDICT_META[result.verdict];
  const current = cases?.[selected];

  return (
    <div className="space-y-3 p-4">
      <div className="flex flex-wrap items-center gap-x-4 gap-y-1 rounded-lg bg-secondary px-4 py-3">
        <span
          className={cn(
            "flex items-center gap-2 text-lg font-semibold",
            verdict.ok ? "text-primary" : "text-destructive"
          )}
        >
          <span
            className={cn(
              "grid h-5 w-5 place-items-center rounded-full text-white",
              verdict.ok ? "bg-primary" : "bg-destructive"
            )}
          >
            {verdict.ok ? (
              <Check className="h-3 w-3" aria-hidden="true" />
            ) : (
              <X className="h-3 w-3" aria-hidden="true" />
            )}
          </span>
          {verdict.label}
        </span>

        <span className="font-mono text-xs text-muted-foreground">
          Runtime: {result.executionTimeMs ?? "—"} ms
          <span className="mx-2">|</span> {memoryLabel}:{" "}
          {formatProblemMemory(result.memoryUsedKb)}
        </span>

        {runMode ? (
          <Badge variant="outline" className="ml-auto font-normal">
            Run: public testcases only
          </Badge>
        ) : null}
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="rounded-lg bg-secondary p-3">
          <p className="text-xs text-muted-foreground">Status</p>
          <p
            className={cn(
              "font-semibold",
              verdict.ok ? "text-primary" : "text-destructive"
            )}
          >
            {verdict.ok ? "Passed" : "Failed"} ({result.passTestCases ?? 0}/
            {result.totalTestCases ?? 0})
          </p>
        </div>

        {result.memoryPercentile != null ? (
          <div className="rounded-lg bg-secondary p-3">
            <p className="text-xs text-muted-foreground">Memory Percentile</p>
            <p className="font-semibold">Beats {result.memoryPercentile} %</p>
          </div>
        ) : null}
      </div>

      {result.errorMessage ? (
        <pre className="max-h-40 overflow-auto rounded-lg bg-black p-3 font-mono text-xs text-red-300">
          {result.errorMessage}
        </pre>
      ) : null}

      {cases && cases.length > 0 ? (
        <>
          <Tabs
            value={String(selected)}
            onValueChange={(value) => setSelected(Number(value))}
          >
            <TabsList className="h-auto w-full flex-wrap justify-start gap-1 bg-transparent p-0">
              {cases.map((c, i) => (
                <TabsTrigger
                  key={c.index ?? i}
                  value={String(i)}
                  className="gap-1.5 rounded-md border px-2.5 py-1 text-xs data-[state=active]:bg-accent"
                >
                  <span
                    className={cn(
                      "h-1.5 w-1.5 rounded-full",
                      CASE_VERDICT_CLASS[c.verdict]
                    )}
                    aria-hidden="true"
                  />
                  Case {i + 1}
                  {c.hidden ? (
                    <span className="text-muted-foreground">(hidden)</span>
                  ) : null}
                </TabsTrigger>
              ))}
            </TabsList>
          </Tabs>

          {current ? (
            <div className="space-y-2 rounded-lg border p-3">
              {current.hidden ? (
                <p className="text-sm text-muted-foreground">
                  Hidden testcase: only verdict is shown (
                  {current.verdict === "SKIPPED"
                    ? "skipped"
                    : PROBLEM_VERDICT_META[
                        current.verdict as Exclude<ProblemCaseVerdict, "SKIPPED">
                      ]?.label ?? current.verdict}
                  ), data is private.
                </p>
              ) : current.verdict === "SKIPPED" ? (
                <p className="text-sm text-muted-foreground">
                  Skipped: testing stopped on the first failing test case (Fail-Fast).
                </p>
              ) : current.verdict === "TLE" ||
                current.verdict === "MLE" ||
                current.verdict === "RE" ? (
                <p className="text-sm text-destructive">
                  {PROBLEM_VERDICT_META[current.verdict].label} on this testcase.
                </p>
              ) : (
                <>
                  <CodeBox label="Input">{current.input}</CodeBox>
                  <ProblemDiffView
                    expected={current.expected ?? ""}
                    actual={current.actual ?? ""}
                  />
                </>
              )}
            </div>
          ) : null}
        </>
      ) : null}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";

export interface ProblemDiffViewProps {
  expected: string;
  actual: string;
  className?: string;
}

interface DiffRow {
  text?: string;
  diff: boolean;
}

function toLines(value: string): string[] {
  return value.replace(/\r\n/g, "\n").replace(/\n$/, "").split("\n");
}

function DiffColumn({
  title,
  rows,
  tone,
}: {
  title: string;
  rows: DiffRow[];
  tone: "red" | "green";
}) {
  return (
    <div className="min-w-0">
      <p className="mb-1 font-mono text-[11px] uppercase text-muted-foreground">
        {title}
      </p>
      <div className="overflow-auto rounded-md border bg-black/90 py-1 font-mono text-xs text-white">
        {rows.map((row, i) => (
          <div
            key={i}
            className={cn(
              "flex gap-2 px-2 py-0.5",
              row.diff &&
                (tone === "red" ? "bg-red-500/25" : "bg-emerald-500/25")
            )}
          >
            <span className="w-4 shrink-0 select-none text-right text-white/40">
              {i + 1}
            </span>
            {row.text === undefined ? (
              <span className="italic text-white/40">(missing line)</span>
            ) : (
              <span className="whitespace-pre-wrap break-all">
                {row.text === "" ? " " : row.text}
              </span>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * Side-by-side expected vs. actual output.
 *
 * Compares line by line, ignoring trailing whitespace on each line, which
 * matches how the judge compares program output.
 */
export function ProblemDiffView({
  expected,
  actual,
  className,
}: ProblemDiffViewProps) {
  const expectedLines = toLines(expected);
  const actualLines = toLines(actual);
  const total = Math.max(expectedLines.length, actualLines.length);

  const rows = Array.from({ length: total }, (_, i) => ({
    expected: expectedLines[i],
    actual: actualLines[i],
    diff: expectedLines[i]?.trimEnd() !== actualLines[i]?.trimEnd(),
  }));

  return (
    <div className={cn("grid grid-cols-1 gap-2 sm:grid-cols-2", className)}>
      <DiffColumn
        title="Output (your code)"
        tone="red"
        rows={rows.map((r) => ({ text: r.actual, diff: r.diff }))}
      />
      <DiffColumn
        title="Expected output"
        tone="green"
        rows={rows.map((r) => ({ text: r.expected, diff: r.diff }))}
      />
    </div>
  );
}

export type ProblemDifficulty = "EASY" | "MEDIUM" | "HARD";

export type ProblemVerdict =
  | "AC"
  | "WA"
  | "TLE"
  | "MLE"
  | "CE"
  | "RE"
  | "SV"
  | "FLAGGED_CHEATING";

/** Per-testcase verdicts reported by the judge. */
export type ProblemCaseVerdict = "AC" | "WA" | "TLE" | "MLE" | "RE" | "SKIPPED";

/**
 * The problem model the block renders.
 *
 * This file intentionally declares its own types instead of importing from the
 * host application's `@/types/api`. Keeping the block self-contained is what
 * makes `shadcn add problem-detail` work in any project: the host passes its
 * own domain models, and TypeScript's structural typing accepts them as long
 * as the shapes line up.
 */
export interface ProblemDetailProblem {
  id: number;
  title: string;
  /** Markdown source. */
  description: string;
  difficulty: ProblemDifficulty;
  timeLimitMs?: number;
  memoryLimitMb?: number;
  /** Lifecycle marker such as DRAFT / REVIEWING / PUBLISHED / ARCHIVED. */
  status?: string;
  likes?: number | null;
  dislikes?: number | null;
}

export interface ProblemDetailTestCase {
  id: number;
  input: string;
  expectedOutput: string;
  isHidden: boolean;
  explanation?: string;
}

export interface ProblemDetailCaseResult {
  index: number;
  verdict: ProblemCaseVerdict;
  hidden: boolean;
  input?: string;
  expected?: string;
  actual?: string;
  timeMs?: number;
}

export interface ProblemDetailSubmission {
  status?: string;
  verdict?: ProblemVerdict | null;
  executionTimeMs?: number | null;
  memoryUsedKb?: number | null;
  passTestCases?: number;
  totalTestCases?: number;
  errorMessage?: string | null;
  memoryPercentile?: number | null;
}

export interface ProblemVerdictMeta {
  label: string;
  ok: boolean;
}

export const PROBLEM_VERDICT_META: Record<ProblemVerdict, ProblemVerdictMeta> = {
  AC: { label: "Accepted", ok: true },
  WA: { label: "Wrong Answer", ok: false },
  TLE: { label: "Time Limit Exceeded", ok: false },
  MLE: { label: "Memory Limit Exceeded", ok: false },
  CE: { label: "Compilation Error", ok: false },
  RE: { label: "Runtime Error", ok: false },
  SV: { label: "Security Violation", ok: false },
  FLAGGED_CHEATING: { label: "Flagged (Cheating)", ok: false },
};

export interface ProblemDifficultyMeta {
  label: string;
  className: string;
}

export const PROBLEM_DIFFICULTY_META: Record<
  ProblemDifficulty,
  ProblemDifficultyMeta
> = {
  EASY: {
    label: "Easy",
    className:
      "border-emerald-500/30 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400",
  },
  MEDIUM: {
    label: "Medium",
    className:
      "border-amber-500/30 bg-amber-500/10 text-amber-600 dark:text-amber-400",
  },
  HARD: {
    label: "Hard",
    className:
      "border-red-500/30 bg-red-500/10 text-red-600 dark:text-red-400",
  },
};

/** Formats a kilobyte reading the way the judge reports it. */
export function formatProblemMemory(kb: number | null | undefined): string {
  if (kb == null) return "—";
  return kb >= 1024 ? `${(kb / 1024).toFixed(1)} MB` : `${kb} KB`;
}

